We formalize this idea as the following constrained empirical risk minimization (ERM) problem, which we call \textit{Pessimistic ERM:}
    given tolerance $\rho\geq 0$, sets of positive and unlabeled samples $P$ and $U$ respectively, and a hypothesis class $\hypo{H}$, the Pessimistic-ERM{} problem is  
    \[
        \operatornamewithlimits{arg\,min}_{H\in \hypo{H}}~~ \frac{\abs{H\cap U}}{\abs{U}}
        \,,\quad\text{ such that}\,,\quad 
        \frac{\abs{H\cap P}}{\abs{P}} \geq 1-\rho
        \,.
        \tag{Pessimistic-ERM{}}
    \]

\label{thm:unifConvergence}
Let $\hypo{F}$ be any concept class on $\mathbb{R}^d$ with finite VC-dimension, \textit{i.e.}{}, $\textrm{\rm VC}{(\hypo{F})}<\infty$, and let $\customcal{D}$ be any distribution over $\mathbb{R}^d$.
For any confidence level $\delta\in (0,\nfrac{1}{2})$ and any fixed set $F^\star\subseteq \mathbb{R}^d$, with probability $1-\delta$, over the draw $X\sim \customcal{D}^n$, every $F\in \hypo{F}$,
\begin{align*}
    \customcal{D}\sinparen{F\triangle F^\star}
        &\leq 
            D_n\sinparen{F\triangle F^\star}
            + \sqrt{
                D_n\sinparen{F\triangle F^\star}
                \cdot 
                s(\hypo{F},n,\delta)
            }
            + 
            4 s(\hypo{F},n,\delta)\,,
        \addtocounter{equation}{1}\tag{\theequation}\label{eq:sampleComplexity:1}\\
        D_n\sinparen{F\triangle F^\star}
        &\leq 
            \customcal{D}\sinparen{F\triangle F^\star}
            + \sqrt{
                \customcal{D}\sinparen{F\triangle F^\star}
                \cdot 
                s(\hypo{F},n,\delta)
            }
            + 
            4 s(\hypo{F},n,\delta)\,,
        \addtocounter{equation}{1}\tag{\theequation}\label{eq:sampleComplexity:2}
\end{align*}
where $s(\hypo{F},n,\delta)$ and $D_n\sinparen{F\triangle F^\star}$ are defined as follows 
\[
    s(\hypo{F},n,\delta) \coloneqq \frac{2\textrm{\rm VC}{(\hypo{F})}\log{(n+1)}+\log{\nfrac{4}{\delta}}}{n}
    \qquadtext{and}
    D_n\sinparen{F\triangle F^\star}
    \coloneqq 
    \frac{\abs{X\cap \sinparen{F\triangle F^\star}}}{\abs{X}}\,.
\]

\begin{align*}
