    \addtocounter{equation}{1}\tag{\theequation}\label{eq:oneSided:empiricalUB}
                    \]

\[
                        \customcal{D}(H\setminus {H^\star}) \leq \varepsilon + \wt{O}\inparen{\sqrt{
