            \end{align*}

\label{lem:main:chaining}
It holds that 
\begin{align*}
    \customcal{D}(\mathbb{R}^d\setminus H_1)
    &\geq \customcal{D}(H_1\setminus H_2) - \gamma^2\\
    &\geq \customcal{D}(H_1\cap H_2\setminus H_3) - 2\gamma^2\\
    &~~\vdots\\
    &\geq \customcal{D}(H_1\cap H_2\cap \dots H_{T-1}\setminus H_T) - (T-1)\gamma^2\,.
\end{align*}

\begin{align*}
                \customcal{D}(H_1\cap H_2\cap \dots \cap H_{T-1}\setminus H_T)
                \leq \frac{1}{T} + (T-1)\gamma^2
                \leq 2\gamma\,.
                \addtocounter{equation}{1}\tag{\theequation}\label{eq:main:chainingGuarantee}
            \end{align*}

\caption{\textsf{Boosted-}$\mathsf{Constrained\text{-}Regression}${}}
\begin{algorithmic}[1]
\Procedure{{\rm \textsf{Boosted-}}$\mathsf{Constrained\text{-}Regression}${}}{$\zeta,\delta,\sigma,q,\alpha,k$}
    \State Initialize variable $i=1$

    \vspace{2mm}

    \State\textit{\#~~Subroutine A (Obtain Samples)}
        \State Obtain sets $P$ and $U$ of $\wt{\Omega}\inparen{
            \inparen{\nfrac{1}{\zeta^2}}\cdot
                \inparen{d^k+\log{\nfrac{1}{\delta}}}
        }$ positive and unlabeled samples \label[step]{step:constReg:getSamples} 
        \item[]\quad~ respectively from the PIU learning model (\cref{prob:PUlearning}) 
        \vspace{4mm}
    \State \textit{\#~~Subroutine B (Solve Constrained Regression)}
    \State Find the optimal solution $p_i(\cdot)$ of the following program for $\rho=\frac{2}{\alpha\sigma} \cdot \zeta^{1/(2q)}$ \label[step]{step:constReg:findP} 
    \changetag{Constrained Regression) \ (#1}
    \[
        \min_{{\rm deg}(p)\leq k} \frac{\sum_{x\in U} \abs{{p(x)}}}{\abs{U}}
        \,,~~
        \text{s.t.}\,,~~
        \frac{\sum_{x\in P} \min\inbrace{p(x), 1}}{\abs{P}}     \geq 1  -  \rho
        \,.
        \addtocounter{equation}{1}\tag{\theequation}\label[program]{eq:constReg:prog}
    \]
    \changetag{#1}
    \State \textit{\#~~This program can be solved by formulating it as a linear program over monomials of degree at}
    \State \textit{\#~~most $k$ and using any polynomial-time linear program solver (see \cref{sec:module:linearProgram} for details)}
    \State Let $H_i=\mathds{1}\sinbrace{p_i(\cdot)\geq t_i}$ where $0\leq t_i\leq 1-\sqrt{\rho}$ is chosen to minimize $\sum_{x\in U}  \mathds{1}\sinbrace{p_i(x)\geq t_i}$\label[step]{step:constReg:selectThreshold}  
    \vspace{4mm}
    \State \textit{\#~~Subroutine C (Boost Performance)}
    \State Repeat the Subroutines A and B for $T=O\sinparen{\inparen{\nfrac{1}{\sqrt{\zeta}}}\cdot \log{\nfrac{1}{\delta}}}$ times to get $H_1,H_2,\dots,H_T$ 
    \State Select fresh sets $P'$ and $U'$ of $\wt{O}\sinparen{\inparen{\nfrac{1}{\zeta}}\cdot \log{\nfrac{1}{\delta}}}$ samples from the PIU model (\cref{prob:PUlearning})\label[step]{step:constReg:freshSamples}
    \State \textbf{return} $H_i$ that minimizes $\abs{H_i\cap U'}$ among $1\leq i\leq T$ 
\EndProcedure
\end{algorithmic}
\label{alg:constReg}

\label{lem:constReg:feasibility:unconditional}
                For each $i$, $H_i$ is feasible for Pessimistic-ERM{} over samples $P_i$ and $U_i$ with tolerance $\rho=
                    \sqrt{\nfrac{2}{(\alpha\sigma)} }\cdot \zeta^{1/(4q)}
                $.

As mentioned above, $H_i$ is the PTF $\mathds{1}\sinbrace{p_i(\cdot)\geq t_i}$ where the polynomial $p_i$ is feasible for \cref{eq:constReg:prog} (Constrained Regression) and the threshold $t_i$ satisfies $0\leq t_i \leq 1- \sqrt{\rho}$.
Since $p_i$ is feasible for \cref{eq:constReg:prog} (Constrained Regression) with positive samples $P_i$, 
\[
    \sum_{x\in P_i} \frac{\min\inbrace{p(x), 1}}{\abs{P_i}}
    \geq 1-\rho\,.
\]
Let ${\rm Unif}(P_i)$ be the uniform distribution over elements of $P_i$.
The result follows by applying Markov's inequality on $\max\inbrace{1-p(x),0}$:
since $1-\min\inbrace{p(x),1}=\max\inbrace{1-p(x),0}$, the above inequality implies that $\operatornamewithlimits{\mathbb{E}}_{{\rm Unif}(P_i)}[\max\inbrace{1-p(x),0}]\leq \rho$.
Hence, by Markov's inequality, for each $\eta\in (0,1)$, 
\[
    \Pr_{x\sim {\rm Unif}(P_i)}[\max\inbrace{1-p(x),0} > \eta]\leq \frac{\rho}{\eta}\,.
    \addtocounter{equation}{1}\tag{\theequation}\label{eq:constReg:feasibility:markov}
\]
Substituting $\eta=\sqrt{\rho}$, it follows that 
\[
    \frac{\sum_{x\in P_i} \mathbb{I}\insquare{   x\in H_i } }{\abs{P_i}}
    =
    \sum_{x\in P_i} 
    \frac{\mathbb{I}\insquare{
        p(x) \geq t_i
