    ~~\Stackrel{\textup{\eqrefform@{\ref{eq:constReg:feasibility:markov}}}}{\geq}~~
    {1-\sqrt{\rho}}\,.
\]
The result follows since $\rho$ is set to be $
    \inparen{\nfrac{2}{(\alpha\sigma)} }\cdot \zeta^{1/(2q)}
    $ in \cref{alg:constReg}.

\[
