The proof of this result uses techniques from \citet{charikar2017learning}.


Fix $\beta= \nfrac{1}{2}$. 
Let the (corrupted) samples be $X=\inbrace{x_1,x_2,\dots,x_n}$ and let $x_1,\dots,x_{r}$ be the set of \textit{uncorrupted} samples from $X$.
For each $i$, define $f_i\colon \mathbb{R}^m\to \mathbb{R}^m$ to be the negative log-likelihood function, \textit{i.e.}{}, 
$f_i(\theta) \coloneqq -\log\inparen{\customcal{E}(x_i; \theta)}$.
Let $\overline{f}\colon \mathbb{R}^m \to \mathbb{R}^m$ be the population log-likelihood, \textit{i.e.}{}, $\overline{f}(\theta)=\operatornamewithlimits{\mathbb{E}}_{z\sim \customcal{E}(\theta^\star)}\insquare{-\log\inparen{z;\theta}}$.
Standard properties of the exponential density (see, \textit{e.g.}{}, \citet{dasgupta2008asymptotic}) imply that:
for all $i$ and $\theta$
\begin{align*}
    \nabla f_i(\theta) &= \nabla A(\theta) - t(x_i)
    ~~\quad\quadtext{and}~~
    \nabla^2 f_i(\theta) = \nabla^2 A(\theta)\,,\\
    \nabla \overline{f}(\theta) &= \nabla A(\theta) - \nabla A(\theta^\star)
    \quadtext{and}~~
    \nabla^2 \overline{f}(\theta) = \nabla^2 A(\theta)\,.
\end{align*}
Where $A\colon \mathbb{R}^m \to \mathbb{R}_{>0}$ is the log-partition function of the exponential family and $t\colon \mathbb{R}^d\to \mathbb{R}^m$ is the sufficient statistic of the exponential family.

\cref{asmp:exponentialFamily} implies that $f_i(\theta)$ and $\overline{f}(\theta)$ are $\lambda$-strongly convex and, hence, we can use \cite[Theorem 6.1]{charikar2017learning}.
Before using \cite[Theorem 6.1]{charikar2017learning} though, we need to establish a spectral bound required by the theorem.
Toward this, observe that for $i$ drawn uniformly from $[r]$ the expectation and variance of $\nabla f_i(\theta) - \nabla \overline{f}(\theta)$ is bounded for any $\theta\in \Theta$ as
\begin{align*}
    \operatornamewithlimits{\mathbb{E}}_{i\sim {\rm Unif}{}([r])}\insquare{\nabla f_i(\theta) - \nabla \overline{f}(\theta)} 
        &= \nabla A(\theta^\star) - \operatornamewithlimits{\mathbb{E}}_{z\sim \customcal{E}(\theta^\star)}[t(z)]
        \tag{as $x_1,\dots,x_r$ are i.i.d.{} from $\customcal{E}(\theta^\star)$}\\
        &= 0 \tag{as $\operatornamewithlimits{\mathbb{E}}_{z\sim \customcal{E}(\theta)}[t(z)]=\nabla A(\theta)$ \cite{dasgupta2008asymptotic}}\,,\\
    \ensuremath{\operatornamewithlimits{\rm Cov}}_{i\sim {\rm Unif}{}([r])}\insquare{\nabla f_i(\theta) - \nabla \overline{f}(\theta)} 
    &= \ensuremath{\operatornamewithlimits{\rm Cov}}_{i\sim {\rm Unif}{}([r])}\insquare{
        A(\theta) - t(x_i)
        - \nabla A(\theta) + \nabla A(\theta^\star)
    }\\
    &= \ensuremath{\operatornamewithlimits{\rm Cov}}_{i\sim {\rm Unif}{}([r])}\insquare{
        - t(x_i)
    }\\
    &=\ensuremath{\operatornamewithlimits{\rm Cov}}_{z\sim \customcal{E}(\theta^\star)}\insquare{t(z)}\tag{as $\operatornamewithlimits{\mathbb{E}}_{z\sim \customcal{E}(\theta)}[t(z)]=\nabla A(\theta)$ \cite{dasgupta2008asymptotic}}\\
    &\preceq \Lambda I\,.
\end{align*}
Now, we can establish a bound on $\min_{1\leq i\leq k}\norm{\theta_i-\theta^\star}_2$ using a straightforward adaptation of the proof of \cite[Corollary 9.1]{charikar2017learning} and then, we show that this implies a bound on $\customcal{R}_{w}$-divergence due to \cref{asmp:exponentialFamily}. 
For completeness, we also include the proof of the bound on $\min_{1\leq i\leq k}\norm{\theta_i-\theta^\star}_2$ below. 

\itparagraph{Bound on the $\customcal{R}_q$ divergence.}
    Using \cite[Proposition B.1]{charikar2017learning} and above bounds on on the covariance and expectation of $\nabla f_i(\theta) - \nabla \overline{f}(\theta)$, implies that with probability at least $1-e^{\Omega(\beta^2\gamma n)}$, there exists a subset $G\subseteq [n]$ of $(1-(\nfrac{\beta}{2}))\gamma n$  ``good'' points that have a spectral bounds of $S=O(\nfrac{\Lambda}{\sqrt{\beta}})$ and (by \cite[Proposition 5.6]{charikar2017learning}) $S_{\sfrac{\beta}{2}}=O(\nfrac{\Lambda}{\beta})$.
    Now we are ready to use \cite[Theorem 6.1]{charikar2017learning}, which gives parameters $\theta_1,\theta_2,\dots,\theta_k$ for $k\leq \inparen{(1-\beta)\gamma}^{-1}$ such that 
    \[
        \min_{1\leq i\leq k}\norm{\theta_i-\theta^\star}_2^2
        \leq 
        O\inparen{
            \inparen{\frac{\Lambda}{\beta\lambda}}^2
            \cdot
            \frac{\log\inparen{\nfrac{2}{\gamma}}}{\gamma}
        }
        \addtocounter{equation}{1}\tag{\theequation}\label{eq:application:listDecoding:paramDistance}
        \,.
    \] 

\medskip 

\noindent Next, we project $\theta_1,\dots,\theta_k$ to $\Theta(\eta)$.
With some abuse of notation, let the projections be $\theta_1,\dots,\theta_k$.
Since $\theta^\star\in \Theta(\eta)$, this only reduces the distance between $\theta_i$ and $\theta^\star$ for all $1\leq i\leq k$.
Define 
\[
    R = O\inparen{
            {\frac{\Lambda}{\lambda}}
            \cdot
            \sqrt{
                \frac{\log\inparen{\nfrac{2}{\gamma}}}{\gamma}
            }
        }
    \,.
\]
We claim that for any $i$, the $\customcal{R}_{w}$ divergence between $\customcal{E}(\theta_i)$ and $\customcal{E}(\theta^\star)$ is bounded as desired (in both directions).
To show this, we prove the following fact. 
    \begin{fact}\label{fact:app}
        For any $\theta_1,\theta_2\in \Theta(\eta)$ that satisfy that $\norm{\theta_1-\theta_2}_2^2\leq R$, it holds that 
        \[
            \operatornamewithlimits{\mathbb{E}}_{x\sim \customcal{E}(\theta_2)}\insquare{
            \inparen{
                \frac{
                    \customcal{E}(x; \theta_1)
                }{
                    \customcal{E}(x; \theta_2)
                }
            }^{w}
            }
            \leq \exp\inparen{
                \Lambda ({w}R)^2 
            }\,.
        \]
        Where the ${w}$ is as in the statement of \cref{thm:listDecoding:expFamily}.
    \end{fact}
    \begin{proof}[Proof of \cref{fact:app}]
        Observe that 
        \begin{align*}
